/**
 * Human-editable workload definition for the unified k6 suite.
 *
 * 1) Keep the route inventory generated from Express source; edit this file instead.
 * 2) Reads are eligible by default. Protected reads need a matching bearer token.
 * 3) Every mutation is opt-in twice: enable it here AND dispatch with include_mutations=true.
 * 4) Every path parameter / write payload must be supplied explicitly. No fake IDs or
 *    guessed payloads are generated by the runner.
 */
export default {
  version: 1,
  apiPrefix: '/api/v1',
  defaults: {
    publicReads: true,
    authenticatedReads: true,
    operationWeight: 1,
    timeout: '15s',
    thinkTimeSeconds: 0.05,
    maxRedirects: 2,
    discardResponseBodies: false,
    maxErrorSamplesPerVu: 2,
  },

  // Optional per-domain weighting. Values are relative weights, not percentages.
  // Remove a group or set enabled:false to exclude it from a run.
  groups: {
    classifieds: { enabled: true, weight: 2.5 },
    commerce: { enabled: true, weight: 2.0 },
    services: { enabled: true, weight: 1.5 },
    discovery: { enabled: true, weight: 2.0 },
    identity: { enabled: true, weight: 1.0 },
    engagement: { enabled: true, weight: 1.0 },
    trust: { enabled: true, weight: 0.5 },
    platform: { enabled: true, weight: 0.5 },
    'go-worker': { enabled: true, weight: 0.75 },
    'edge-ops': { enabled: true, weight: 0.25 },
    'frontend-api': { enabled: true, weight: 0.5 },
    'keepalive-worker': { enabled: true, weight: 0.1 },
  },

  // Shared headers are useful for signed internal Worker calls. Use $env:NAME values.
  // Operation headers override shared values.
  globalHeaders: {},

  // Exact keys are "METHOD /path/from/route-inventory".
  // Per-operation overrides are intentionally explicit and easy to diff.
  operations: {
    'GET /ads': { enabled: true, weight: 10, query: { page: 1, limit: 20, sortBy: 'createdAt', sortOrder: 'desc' } },
    'GET /ads/search': { enabled: true, weight: 2, query: { q: 'phone', page: 1, limit: 10 } },
    'GET /categories': { enabled: true, weight: 3 },
    'GET /home': { enabled: true, weight: 2 },
    'GET /home/static': { enabled: true, weight: 4 },

    // OAuth browser-navigation routes are intentionally excluded from API load.
    'GET /auth/google': { enabled: false },
    'GET /auth/google/callback': { enabled: false },
    'GET /auth/google/failure': { enabled: false },
    'GET /products': { enabled: true, weight: 5, query: { page: 1, limit: 20 } },
    'GET /stores': { enabled: true, weight: 4, query: { page: 1, limit: 20 } },
    'GET /service-categories': { enabled: true, weight: 2 },
    'GET /service-listings': { enabled: true, weight: 3, query: { page: 1, limit: 20 } },
    'GET /service-providers': { enabled: true, weight: 2, query: { page: 1, limit: 20 } },
    'GET /service-providers/nearby': { enabled: true, weight: 1, query: { lat: '$env:LOAD_TEST_LAT', lng: '$env:LOAD_TEST_LNG', radius: 10, limit: 10 } },
    'GET /search': { enabled: true, weight: 2, query: { q: 'phone', limit: 10 } },
    'GET /search/suggestions': { enabled: true, weight: 1, query: { q: 'phone' } },

    // Add real fixture IDs here before enabling detail/relationship operations.
    // Values may be literal strings or "$env:VARIABLE_NAME" references.
    'GET /ads/:id': { enabled: true, params: { id: '$env:LOAD_TEST_AD_ID' }, weight: 2 },
    'GET /products/:id': { enabled: true, params: { id: '$env:LOAD_TEST_PRODUCT_ID' }, weight: 2 },
    'GET /stores/:id': { enabled: true, params: { id: '$env:LOAD_TEST_STORE_ID' }, weight: 2 },
    'GET /service-listings/:id': { enabled: true, params: { id: '$env:LOAD_TEST_SERVICE_LISTING_ID' }, weight: 1 },
    'GET /health/outbox': { enabled: false, weight: 0.2 },

    // Examples for controlled writes. Replace these payloads with valid test fixtures,
    // then dispatch with include_mutations=true. Avoid DELETE/bulk/admin actions unless
    // the target database is disposable and the selected records are dedicated fixtures.
    'POST /ads': {
      enabled: false,
      bodyType: 'multipart',
      body: {
        fields: {
          title: 'Load test ad {{RUN_ID}}-{{VU}}-{{ITER}}',
          description: 'Disposable load-test record; safe to delete after the run.',
          price: '10',
          city: 'Gaza',
        },
        files: [{
          field: 'images',
          path: './apps/api/load-tests/fixtures/marketplat-load-test.png',
          filename: 'marketplat-load-test.png',
          contentType: 'image/png',
        }],
      },
      expectedStatuses: [201],
      weight: 1,
    },
    'POST /analytics/events': {
      enabled: false,
      bodyType: 'json',
      body: { events: [{ event: 'PAGE_VIEW', eventId: '{{RUN_ID}}-{{VU}}-{{ITER}}', sessionId: '{{RUN_ID}}-{{VU}}', path: '/load-test' }] },
      expectedStatuses: [200, 201, 202],
      weight: 1,
    },

    // POST /batch is a read-only transport but requires a requests[] envelope.
    'POST /batch': {
      enabled: false,
      readOnly: true,
      bodyType: 'json',
      body: {
        requests: [
          { id: 'categories', url: '/categories' },
          { id: 'home-static', url: '/home/static' },
        ],
      },
      expectedStatuses: [200],
      weight: 1,
    },

    // Go Worker HTTP surface. Every route stays disabled unless explicitly
    // enabled here and dispatched with include_internal=true. The gateway
    // ingress token is supplied separately by LOAD_TEST_GO_WORKER_TOKEN.
    // Add request bodies only for the specific jobs whose contract you know.
    'GET /internal/diagnostics': { enabled: false, weight: 0.5 },
    'GET /internal/search/index-status': { enabled: false, weight: 0.5 },
    'GET /internal/media/cleanup/status': { enabled: false, weight: 0.25 },
    'GET /internal/outbox/worker-status': { enabled: false, weight: 0.25 },
    'GET /internal/push/dispatch/worker-status': { enabled: false, weight: 0.25 },

    // Cloudflare Worker control plane. Header tokens are injected only for
    // these operations; no registry writes or cache purges run by default.
    'GET /__gateway/registry': {
      enabled: false,
      headers: { 'x-gateway-admin-token': '$env:LOAD_TEST_EDGE_GATEWAY_ADMIN_TOKEN' },
      expectedStatuses: [200],
    },
    'POST /__gateway/registry': {
      enabled: false,
      readOnly: true,
      bodyType: 'json',
      body: { action: 'probe' },
      headers: { 'x-gateway-admin-token': '$env:LOAD_TEST_EDGE_GATEWAY_ADMIN_TOKEN' },
      expectedStatuses: [200],
    },
    'PUT /__gateway/registry': {
      enabled: false,
      headers: { 'x-gateway-admin-token': '$env:LOAD_TEST_EDGE_GATEWAY_ADMIN_TOKEN' },
    },
    'GET /__gateway/feature-flags': {
      enabled: false,
      headers: { 'x-feature-flags-token': '$env:LOAD_TEST_EDGE_FEATURE_FLAGS_TOKEN' },
      expectedStatuses: [200],
    },
    'PUT /__gateway/feature-flags': {
      enabled: false,
      headers: {
        'x-feature-flags-token': '$env:LOAD_TEST_EDGE_FEATURE_FLAGS_TOKEN',
        'x-feature-flags-actor': '$env:LOAD_TEST_EDGE_FEATURE_FLAGS_ACTOR',
      },
    },
    'GET /__gateway/public-feature-flags': { enabled: false, expectedStatuses: [200] },
    'POST /__purge__': {
      enabled: false,
      headers: { 'x-purge-token': '$env:LOAD_TEST_EDGE_PURGE_TOKEN' },
    },

    // Next.js Route Handlers are tested against LOAD_TEST_FRONTEND_TARGET,
    // never against the API origin. All are opt-in through include_internal.
    'GET /api/public/feature-flags': { enabled: true, expectedStatuses: [200] },
    'GET /api/admin/debug-toggle': { enabled: true, expectedStatuses: [200] },
    'POST /api/admin/debug-toggle': {
      enabled: false,
      allowEmptyBody: true,
      headers: {
        cookie: '$env:LOAD_TEST_FRONTEND_ADMIN_COOKIE',
        origin: '{{FRONTEND_ORIGIN}}',
      },
      expectedStatuses: [200],
    },
    'DELETE /api/admin/debug-toggle': {
      enabled: false,
      headers: {
        cookie: '$env:LOAD_TEST_FRONTEND_ADMIN_COOKIE',
        origin: '{{FRONTEND_ORIGIN}}',
      },
      expectedStatuses: [200],
    },
    'GET /api/admin/feature-flags': { enabled: true, expectedStatuses: [200] },
    'PUT /api/admin/feature-flags': { enabled: false },
    'GET /api/admin/gateway/registry': { enabled: true, expectedStatuses: [200] },
    'PUT /api/admin/gateway/registry': { enabled: false },
    'POST /api/admin/gateway/registry': { enabled: false },
    'GET /api/internal/cache/revalidate': { enabled: true, expectedStatuses: [405] },
    'POST /api/internal/cache/revalidate': {
      enabled: false,
      bodyType: 'json',
      body: { tags: ['route:home'] },
      signing: {
        type: 'hmac-sha256',
        secret: '$env:LOAD_TEST_CACHE_REVALIDATION_SECRET',
        timestampHeader: 'x-marketplat-timestamp',
        signatureHeader: 'x-marketplat-signature',
      },
      expectedStatuses: [200],
    },

    // HTTP status endpoint of the scheduled keepalive Worker.
    'GET /': { enabled: true, expectedStatuses: [200] },
  },

  // Path parameter values shared between operations. Prefer operation-specific values
  // above because "id" can refer to unrelated resource types.
  globalParams: {},

  // Query string defaults applied to every operation in a group can be declared here.
  globalQuery: {},

  thresholds: {
    p95Ms: 1500,
    p99Ms: 3000,
    errorRate: 0.02,
    checksRate: 0.98,
  },
};
